/*  /research/ — index and article reader over the Markdown posts.
 *
 *  One page serves both views so that publishing is only ever "copy the .md
 *  into research/posts/ and rebuild posts.json":
 *
 *    /research/                     the index, from posts.json
 *    /research/?p=<slug>            one article, from its .md
 *
 *  posts.json is generated by scripts/build-index.py (deploy.sh runs it) and
 *  is the only place a filename is resolved — the ?p slug is matched against
 *  that list rather than pasted into a path, so a crafted slug cannot reach
 *  anything outside research/posts/.
 */

(function () {
  "use strict";

  var view = document.getElementById("view");
  if (!view) return;

  var MANIFEST = "/research/posts.json";
  var POSTS_DIR = "/research/posts/";

  function esc(text) {
    return window.MD.escapeHtml(String(text == null ? "" : text));
  }

  function fail(message, detail) {
    view.innerHTML =
      '<div class="section-head"><h2>Research</h2></div>' +
      '<p class="footnote" style="margin-top:20px">' + esc(message) +
      (detail ? ' <span style="opacity:.7">(' + esc(detail) + ")</span>" : "") +
      "</p>";
  }

  function setMeta(name, value, attr) {
    var key = attr || "name";
    var tag = document.head.querySelector("meta[" + key + '="' + name + '"]');
    if (!tag) {
      tag = document.createElement("meta");
      tag.setAttribute(key, name);
      document.head.appendChild(tag);
    }
    tag.setAttribute("content", value);
  }

  function setCanonical(href) {
    var link = document.head.querySelector('link[rel="canonical"]');
    if (!link) {
      link = document.createElement("link");
      link.rel = "canonical";
      document.head.appendChild(link);
    }
    link.href = href;
  }

  /* ── index ─────────────────────────────────────────────────────────── */

  function renderIndex(posts) {
    document.title = "Research — LinearCode";
    setCanonical("https://linearcode.io/research/");

    var html = '<div class="section-head"><h2>Research</h2></div>';

    if (!posts.length) {
      html += '<p class="footnote" style="margin-top:20px">Nothing published yet.</p>';
      view.innerHTML = html;
      return;
    }

    html += '<div class="paper-list">';
    posts.forEach(function (post) {
      html +=
        '<a class="paper" href="/research/?p=' + encodeURIComponent(post.slug) + '">' +
        '<span class="date">' + esc(post.dateShort) + "</span>" +
        "<span>" +
        "<h3>" + esc(post.title) + "</h3>" +
        (post.description ? "<p>" + esc(post.description) + "</p>" : "") +
        (post.tags && post.tags.length
          ? '<span class="tagrow">' +
            post.tags.map(function (t) { return '<span class="tag">' + esc(t) + "</span>"; }).join("") +
            "</span>"
          : "") +
        "</span></a>";
    });
    html += "</div>";
    view.innerHTML = html;
  }

  /* ── article ───────────────────────────────────────────────────────── */

  function renderArticle(post, source) {
    var parsed = window.MD.parse(source);
    var meta = parsed.meta;
    var title = meta.title || post.title || post.slug;
    var description = meta.description || post.description || "";
    var url = "https://linearcode.io/research/?p=" + encodeURIComponent(post.slug);
    var read = window.MD.readingTime(parsed.body);
    var tags = meta.tags || post.tags || [];

    document.title = title + " — LinearCode Research";
    if (description) {
      setMeta("description", description);
      setMeta("og:description", description, "property");
    }
    setMeta("og:title", title, "property");
    setMeta("og:type", "article", "property");
    setMeta("og:url", url, "property");
    setCanonical(url);

    view.innerHTML =
      '<article class="article">' +
      '<div class="article-head">' +
      '<a class="article-back" href="/research/">' +
      '<svg width="13" height="13" viewBox="0 0 20 20" fill="none" stroke="currentColor" ' +
      'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">' +
      '<path d="M12 5 7 10l5 5"/></svg>Research</a>' +
      "<h1>" + esc(title) + "</h1>" +
      (description ? '<p class="article-deck">' + esc(description) + "</p>" : "") +
      '<div class="article-meta">' +
      (meta.date ? "<time datetime=\"" + esc(meta.date) + '">' +
        esc(window.MD.formatDate(meta.date)) + "</time><span class=\"sep\">·</span>" : "") +
      "<span>" + read.minutes + " min read</span>" +
      (tags.length ? '<span class="sep">·</span>' : "") +
      tags.map(function (t) { return '<span class="tag">' + esc(t) + "</span>"; }).join("") +
      "</div></div>" +
      '<div class="prose">' + window.MD.render(parsed.body) + "</div>" +
      '<p class="article-license">Source: ' +
      '<a href="' + POSTS_DIR + esc(post.file) + '">' + esc(post.file) + "</a></p>" +
      "</article>";

    // A deep link like /research/?p=slug#references cannot resolve until the
    // Markdown has been rendered, so honour the fragment here.
    if (location.hash.length > 1) {
      var target = document.getElementById(decodeURIComponent(location.hash.slice(1)));
      if (target) target.scrollIntoView();
    }
  }

  /* ── boot ──────────────────────────────────────────────────────────── */

  fetch(MANIFEST, { cache: "no-cache" })
    .then(function (response) {
      if (!response.ok) throw new Error("posts.json " + response.status);
      return response.json();
    })
    .then(function (posts) {
      var slug = new URLSearchParams(location.search).get("p");
      if (!slug) return renderIndex(posts);

      var post = posts.filter(function (p) { return p.slug === slug; })[0];
      if (!post) {
        view.innerHTML =
          '<div class="section-head"><h2>Research</h2></div>' +
          '<p class="footnote" style="margin-top:20px">No article named &ldquo;' +
          esc(slug) + '&rdquo;. <a href="/research/">See everything published</a>.</p>';
        return;
      }

      return fetch(POSTS_DIR + post.file, { cache: "no-cache" })
        .then(function (response) {
          if (!response.ok) throw new Error(post.file + " " + response.status);
          return response.text();
        })
        .then(function (source) { renderArticle(post, source); });
    })
    .catch(function (error) {
      fail("Could not load the research index.", error.message);
    });
})();
